package com.immersio.subscriptions.api; import com.immersio.subscriptions.api.dto.*; import com.immersio.subscriptions.service.*; import com.immersio.shared.dto.ApiResponse; import com.immersio.shared.security.JwtTokenProvider; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/subscription") public class SubscriptionController {private final SubscriptionService s;private final JwtTokenProvider jwt;public SubscriptionController(SubscriptionService s,JwtTokenProvider j){this.s=s;jwt=j;}private UUID u(String h){return jwt.extractUserId(h.replace("Bearer ",""));}@PostMapping("/upgrade") public ApiResponse<Void> upgrade(@RequestHeader("Authorization")String h,@RequestBody UpgradeSubscriptionRequest r){s.upgradeSubscription(u(h),r);return ApiResponse.successResult(null);}@PostMapping("/create-payment") public ApiResponse<CreatePaymentResponse> create(@RequestHeader("Authorization")String h,@RequestBody CreatePaymentRequest r){return ApiResponse.successResult(s.createPaymentUrl(u(h),r));}@GetMapping("/payos-return") public ApiResponse<PaymentReturnResult> ret(@RequestParam(required=false)String orderCode,@RequestParam(required=false)String txnRef,@RequestParam(defaultValue="PAID")String status){return ApiResponse.successResult(s.handlePaymentReturn(orderCode!=null?orderCode:txnRef,status));}@PostMapping("/payos-webhook") public ApiResponse<Void> webhook(@RequestBody(required=false)Map<String,Object> body,@RequestParam(required=false)String orderCode,@RequestParam(required=false)String txnRef,@RequestParam(defaultValue="PAID")String status){String ref=orderCode!=null?orderCode:txnRef;String actualStatus=status;if(body!=null){if(ref==null&&body.get("orderCode")!=null)ref=String.valueOf(body.get("orderCode"));if(ref==null&&body.get("txnRef")!=null)ref=String.valueOf(body.get("txnRef"));if(body.get("status")!=null)actualStatus=String.valueOf(body.get("status"));}s.handlePayOsWebhook(ref,actualStatus);return ApiResponse.successResult(null);}}
